import type { Puzzle } from '../core/puzzle';
import index from './packs.json';
import { levelId, rawToPuzzle, type RawLevel } from './raw';

export { levelId, rawToPuzzle, type RawLevel } from './raw';

export interface Level {
  id: string;
  packId: string;
  /** 1-based position within its pack. */
  number: number;
  puzzle: Puzzle;
}

/** Pack metadata (one pack per board size), available without loading any boards. Generated by scripts/build-levels.ts. */
export interface Pack {
  id: string;
  size: number;
  /** e.g. "7×7" */
  label: string;
  /** Level ids in play order, for solved counts. */
  levelIds: string[];
}

/** In ascending size order. */
export const PACKS: Pack[] = (index as Omit<Pack, 'label'>[]).map((p) => ({ ...p, label: `${p.size}×${p.size}` }));

const loaders = import.meta.glob<RawLevel[]>('./data/*.json', { import: 'default' });
const cache = new Map<string, Promise<Level[]>>();

/** Load a pack's levels (each pack is its own lazily fetched chunk). */
export function loadPack(packId: string): Promise<Level[]> {
  let levels = cache.get(packId);
  if (!levels) {
    const load = loaders[`./data/${packId}.json`];
    if (!load) return Promise.reject(new Error(`Unknown pack ${packId}`));
    levels = load().then((raw) =>
      raw.map((l, i) => ({
        id: levelId(l.board),
        packId,
        number: i + 1,
        puzzle: rawToPuzzle(l),
      })),
    );
    levels.catch(() => cache.delete(packId));
    cache.set(packId, levels);
  }
  return levels;
}
